export const SQLX_SAMPLE = `config {
  type: "incremental",
  schema: "analytics",
  name: "fct_clinical_patients",
  uniqueKey: ["patient_id"],
  bigquery: {
    partitionBy: "DATE(ingest_date)"
  },
  tags: ["marts", "clinical"]
}

js {
  const { scd1Load } = require("includes/udfs");
}

-- Generated by Mapfl0w from sttm_clinical.csv (20 of 23 rows)
-- Rows 3, 9, 17 excluded: status "In Progress"

SELECT
  CAST(src.patient_id AS STRING)                    AS patient_id,
  INITCAP(TRIM(src.first_name))                     AS first_name,
  INITCAP(TRIM(src.last_name))                      AS last_name,
  LOWER(src.email_address)                          AS email_address,
  PARSE_DATE('%Y-%m-%d', src.dob_raw)               AS date_of_birth,
  CAST(src.weight_kg AS INT64)                      AS weight,        -- Row 12: lossy FLOAT -> INT
  ROUND(src.height_cm / 2.54, 1)                    AS height_in,     -- Row 8: translated from Python
  CASE
    WHEN src.gender_code = 'M' THEN 'Male'
    WHEN src.gender_code = 'F' THEN 'Female'
    ELSE 'Unknown'
  END                                               AS gender,
  COALESCE(src.primary_provider_id, 'UNASSIGNED')   AS provider_id,
  SAFE_CAST(src.risk_score AS NUMERIC)              AS risk_score,
  src.facility_code                                 AS facility_code,
  TIMESTAMP(src.admitted_at, 'UTC')                 AS admitted_at,
  CURRENT_TIMESTAMP()                               AS ingest_date
FROM \${ref("raw", "clinical_patients")} AS src
WHERE src.record_status = 'ACTIVE'
  \${when(incremental(), \`AND src.updated_at > (SELECT MAX(ingest_date) FROM \${self()})\`)}

post_operations {
  \${scd1Load(self(), "patient_id")}
}
`;

