function baseMeta(files = 4): Run["meta"] {
  const list = [
    "source_schema.md",
    "target_schema.md",
    "sttm_clinical.csv",
    "repo_structure.md",
    "udf_definitions.md",
  ];
  return { files: list.slice(0, files), llmAttempts: 2, approvedBy: "kapil", workflowId: "wf_9d21" };
}

